import {
    Table,
    BooleanColumn,
    TranslatedFieldColumn,
    DomainIdColumn,
    ReferenceColumn,
    StringColumn,
    DomainPathColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const analytics_dashboard = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    audit: true,
    display: 'name',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Analytics Dashboard',
    name: 'analytics_dashboard',
    schema: {
        active: BooleanColumn({
            audit: true,
            default: true,
            label: 'Active',
        }),
        description: TranslatedFieldColumn({
            audit: true,
            label: 'Description',
            maxLength: 4000,
        }),
        certified: BooleanColumn({
            audit: true,
            default: false,
            label: 'Certified',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: 'Domain',
        }),
        sys_overrides: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Overrides',
            referenceTable: 'analytics_dashboard',
        }),
        base_dashboard: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'clear',
            label: 'Base Dashboard',
            referenceTable: 'analytics_dashboard',
        }),
        ready_to_migrate: StringColumn({
            default: 'Not Applicable',
            dropdown: 'dropdown_with_none',
            label: 'Ready to migrate',
        }),
        name: TranslatedFieldColumn({
            audit: true,
            label: 'Name',
            mandatory: true,
            maxLength: 100,
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
    textIndex: true,
})
